def transform(grid):
 out=[r[:] for r in grid]; h=len(grid); w=len(grid[0])
 for r in range(h):
  for c in range(w):
   if grid[r][c]==7: continue
   for dr,dc in ((0,1),(1,0)):
    rr,cc=r+dr,c+dc
    while 0<=rr<h and 0<=cc<w and grid[rr][cc]==7: rr+=dr; cc+=dc
    if 0<=rr<h and 0<=cc<w and grid[rr][cc]==grid[r][c]:
     x,y=r+dr,c+dc
     while (x,y)!=(rr,cc): out[x][y]=3; x+=dr; y+=dc
 return out
